// ***************
// Filename: spi_top.sv
// Author: FPGA Cores 4 U
// Description: spi_master with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map spi_master_regs
//   (u_regs, src/include/spi_master_regs.sv, ID "SPIM", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic spi_master (u_core,
//   src/spi_master.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   spi_master_regs.json and the ports of spi_master: regenerate after
//   changing either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module spi_top #(
  parameter int CLK_HZ = 100_000_000,
  parameter int SCLK_HZ = 1_000_000,
  parameter int DATA_W = 32,
  parameter int NUM_CS = 4,
  parameter int FIFO_DEPTH = 512
) (
  input  logic              aclk,
  input  logic              aresetn,
  input  logic [7:0]        s_axil_awaddr,
  input  logic              s_axil_awvalid,
  output logic              s_axil_awready,
  input  logic [31:0]       s_axil_wdata,
  input  logic [3:0]        s_axil_wstrb,
  input  logic              s_axil_wvalid,
  output logic              s_axil_wready,
  output logic [1:0]        s_axil_bresp,
  output logic              s_axil_bvalid,
  input  logic              s_axil_bready,
  input  logic [7:0]        s_axil_araddr,
  input  logic              s_axil_arvalid,
  output logic              s_axil_arready,
  output logic [31:0]       s_axil_rdata,
  output logic [1:0]        s_axil_rresp,
  output logic              s_axil_rvalid,
  input  logic              s_axil_rready,
  input  logic [DATA_W-1:0] s_axis_tdata,
  input  logic              s_axis_tvalid,
  output logic              s_axis_tready,
  input  logic              s_axis_tlast,
  output logic [DATA_W-1:0] m_axis_tdata,
  output logic              m_axis_tvalid,
  input  logic              m_axis_tready,
  output logic              m_axis_tlast,
  output logic              spi_sclk_o,
  output logic              spi_mosi_o,
  input  logic              spi_miso_i,
  output logic [NUM_CS-1:0] spi_cs_n_o
);
  // register ports between the register map and the logic
  logic [15:0] cfg_ctrl;
  logic [15:0] cfg_div;
  logic [5:0] cfg_word_len;
  logic [31:0] cfg_status;
  logic cfg_status_wr;
  logic [31:0] sts_status;

  spi_master_regs #(
    .DIV_RST((CLK_HZ / (2 * SCLK_HZ)) - 1)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(),
    .div_o(cfg_div),
    .div_wr_o(),
    .word_len_o(cfg_word_len),
    .word_len_wr_o(),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status)
  );
  spi_master #(
    .CLK_HZ(CLK_HZ),
    .SCLK_HZ(SCLK_HZ),
    .DATA_W(DATA_W),
    .NUM_CS(NUM_CS),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis_tdata,
    .s_axis_tvalid,
    .s_axis_tready,
    .s_axis_tlast,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .spi_sclk_o,
    .spi_mosi_o,
    .spi_miso_i,
    .spi_cs_n_o,
    .cfg_ctrl,
    .cfg_div,
    .cfg_word_len,
    .cfg_status,
    .cfg_status_wr,
    .sts_status
  );
endmodule
